/* Use the selected town illustration; separate buildings/character and sort by foot depth. */
const GameArt={
  world(){
    const doc=new DOMParser().parseFromString(Art.town(),'image/svg+xml'),svg=doc.documentElement,ns='http://www.w3.org/2000/svg';
    svg.setAttribute('class','game-map-art');svg.setAttribute('aria-label','可探索的小镇：储蓄小屋、愿望工坊和委托小铺');
    svg.querySelector(':scope > rect')?.remove();
    const actors=doc.createElementNS(ns,'g');actors.setAttribute('id','world-actors');
    const houses=[['445 99','wish',285],['192 184','savings',365],['572 263','tasks',386]];
    for(const [translate,id,depth] of houses){const node=Array.from(svg.children).find(n=>n.getAttribute('transform')===`translate(${translate})`);node.setAttribute('data-depth',depth);node.setAttribute('data-place',id);node.setAttribute('class','world-house');node.setAttribute('id','house-'+id);actors.append(node);}
    Array.from(svg.children).find(n=>n.getAttribute('transform')==='translate(370 314)')?.remove();
    for(const node of Array.from(svg.children)){if(node.getAttribute('fill')==='#7e9f70'||node.getAttribute('stroke')==='#a78f66')node.remove();}
    svg.querySelector('text')?.remove();
    const decor=doc.createElementNS(ns,'g');decor.innerHTML=`<g class="garden-bed"><path d="m135 341 39-19 41 21-39 20Z" fill="#a7946d"/><path d="m143 339 30-13 31 16-28 15Z" fill="#c9b78c"/><g fill="#688c60"><path d="M158 343q-17-22 1-14 11-18 6 5l-7 10M181 348q-14-24 3-13 15-15 7 5l-10 8"/></g></g><g class="world-mailbox" data-place="journal"><path d="M361 402v27" stroke="#a98d67" stroke-width="5"/><path d="m348 386 17-8 20 10v24l-18 8-19-10Z" fill="#cfb68d"/><path d="m344 386 20-14 24 15-21 11Z" fill="#a9b6a0"/><path d="m354 395 15 7" stroke="#f6edce" stroke-width="3"/><path d="M381 392v-17l10 4-10 4" fill="#d9a076" stroke="#b48864" stroke-width="2"/></g><g class="world-flowers"><path d="m455 438 12 6m-6-9 12 6" stroke="#9bad7e" stroke-width="3"/><circle cx="459" cy="434" r="5" fill="#e9bba4"/><circle cx="473" cy="438" r="4" fill="#efe2a5"/></g><g class="world-sign"><path d="M415 404v25" stroke="#ac9573" stroke-width="4"/><path d="m398 393 30 7 8 7-10 2-29-8Z" fill="#efe3bc"/><path d="m420 390 19-6 7 3-8 6-18 5Z" fill="#d4c2a0"/></g>`;
    svg.append(decor);
    const trees=[[145,283,24,35,333],[393,209,23,33,241],[710,288,22,38,334]];
    for(const [x,y,rx,ry,depth] of trees){const tree=doc.createElementNS(ns,'g');tree.setAttribute('data-depth',depth);tree.setAttribute('class','world-tree');tree.innerHTML=`<ellipse cx="${x}" cy="${depth}" rx="${rx+5}" ry="8" fill="#809879" opacity=".23"/><path d="M${x} ${y+15}v${depth-y-15}" stroke="#a78f66" stroke-width="7"/><ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="#7e9f70"/><path d="M${x} ${y+15}v${depth-y-15}" stroke="#a78f66" stroke-width="6"/>`;actors.append(tree);}
    const growthScale=state.bonusEarned>=100?.62:state.bonusEarned>0?.54:.42;
    const growth=doc.createElementNS(ns,'g');growth.setAttribute('data-depth','449');growth.setAttribute('id','world-growth');growth.setAttribute('data-place','growth');growth.innerHTML=`<ellipse cx="490" cy="449" rx="31" ry="10" fill="#92a98a"/><g transform="translate(${490-91*growthScale} ${449-148*growthScale}) scale(${growthScale})">${Art.tree().replace(/<svg[^>]*>|<\/svg>/g,'')}</g><g class="growth-stars" fill="#e7ca77"><path d="m475 386 2-6 2 6 6 2-6 2-2 6-2-6-6-2Z"/><circle cx="512" cy="394" r="3"/></g>`;actors.append(growth);
    const player=doc.createElementNS(ns,'g');player.setAttribute('id','game-player');player.setAttribute('data-depth','380');player.innerHTML=`<ellipse cx="0" cy="-1" rx="17" ry="5" fill="#6b8569" opacity=".32"/><g id="player-visual"><g transform="translate(-28 -63) scale(.4)">${Art.mascot().replace(/<svg[^>]*>|<\/svg>/g,'')}</g><path class="player-scarf" d="m-8-20 17 1-1 5-17-1-4 9-4-3 5-10Z" fill="#b3a2c8"/></g><g class="player-name"><rect x="-30" y="8" width="60" height="20" rx="10" fill="#fff9e5" opacity=".94"/><text x="0" y="22" text-anchor="middle" font-size="11" fill="#667357">${e(state.child)}</text></g>`;actors.append(player);
    svg.append(actors);
    const guide=doc.createElementNS(ns,'g');guide.setAttribute('id','walk-guide');guide.setAttribute('pointer-events','none');guide.innerHTML='<path id="walk-path" fill="none" stroke="#fff6d7" stroke-width="3" stroke-dasharray="3 7" stroke-linecap="round"/><g id="walk-target" opacity="0"><ellipse rx="14" ry="7" fill="none" stroke="#f4de9b" stroke-width="3"/><path d="m-5-10 5 5 5-5" fill="none" stroke="#f7eac4" stroke-width="2"/></g>';svg.insertBefore(guide,actors);
    return new XMLSerializer().serializeToString(svg);
  },
  room(kind){const colors={tasks:['#dfb88e','#f2dbb3','#b3c6a1'],savings:['#b6c4a1','#e9e6c6','#d7b37e'],wish:['#b6adca','#ebe1cb','#a7bbb1'],growth:['#a6bb91','#e1e9ca','#bcb18e']},c=colors[kind]||colors.savings;return `<svg class="room-art" viewBox="0 0 580 180" aria-hidden="true"><path d="m85 125 190-89 215 87-191 55Z" fill="${c[0]}"/><path d="M85 125V38l190-35v33Z" fill="${c[1]}"/><path d="M275 3 490 42v81L275 36Z" fill="${c[2]}"/><path d="m116 45 53-12v46l-53 15Z" fill="#fcf6df"/><path d="m122 48 41-10v35l-41 11Z" fill="#b3c9bd"/><path d="m142 43 1 35m-20-18 40-10" stroke="#f8f0d2" stroke-width="3"/><g transform="translate(350 52) scale(.52)">${(kind==='wish'?Art.telescope():kind==='tasks'?Art.book():Art.tree()).replace(/<svg[^>]*>|<\/svg>/g,'')}</g><path d="m174 110 81-36 80 31-83 42Z" fill="#ead3a5"/><path d="m174 110 78 37v15l-78-36Z" fill="#c9aa7f"/><path d="m252 147 83-42v16l-83 41Z" fill="#bba17a"/><g transform="translate(258 61) scale(.46)">${Art.mascot().replace(/<svg[^>]*>|<\/svg>/g,'')}</g><path d="m383 55 25 6v30l-25-5Z" fill="#f5eccf"/><path d="m389 65 13 4m-13 5 13 3" stroke="#c6b18b" stroke-width="2"/></svg>`;}
};
